// The templates that ship to students. Generated by `npm run content:validate` (also run before every
// build and test run): only templates that pass validation and are "in-review" or "approved" are included.
import generated from "./generated/templates.json";
import { rng } from "./rng";
import { PLAYABLE_STATUSES, type Template } from "./schema";

export interface ManifestEntry {
  template: Template;
  hash: string;
  /** true only for human-approved templates whose content hash still matches the approval */
  countsTowardMastery: boolean;
}
export interface Manifest { generatedBy: string; templates: ManifestEntry[] }

const manifest = generated as unknown as Manifest;

/** Defence in depth: never trust the generated file to have filtered drafts. */
export const CATALOG: ManifestEntry[] = manifest.templates.filter((e) => PLAYABLE_STATUSES.includes(e.template.status))
  .map((e) => ({ ...e, countsTowardMastery: e.countsTowardMastery && e.template.status === "approved" }));

export const entryById = new Map(CATALOG.map((e) => [e.template.id, e]));
export const templatesForChapter = (chapterId: string) => CATALOG.filter((e) => e.template.chapterId === chapterId);

/** A starting question for a chapter: deterministic for a seed, so a refresh shows the same question. */
export function pickEntry(chapterId: string, seed: number): ManifestEntry | undefined {
  const list = templatesForChapter(chapterId);
  return list.length ? rng(seed ^ 0x5bd1e995).pick(list) : undefined;
}
